import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "रिपोर्ट में टोटल प्रोटीन ज़्यादा आया? या डॉक्टर ने प्रोटीन इलेक्ट्रोफोरेसिस करवाने को कहा है? यह टेस्ट क्या है, और इसमें दिखने वाला एम स्पाइक क्या होता है, आखिर तक देखिए.",
 "हमारे खून में कई तरह के प्रोटीन होते हैं. प्रोटीन इलेक्ट्रोफोरेसिस में, खून का सीरम एक जेल पर रखकर, बिजली का करंट दिया जाता है. प्रोटीन अपने आकार और चार्ज के हिसाब से, अलग अलग पट्टियों में बंट जाते हैं.",
 "आमतौर पर पांच हिस्से दिखते हैं. एल्ब्यूमिन, अल्फा वन, अल्फा टू, बीटा, और गामा. गामा हिस्से में इम्यूनोग्लोबुलिन, यानी एंटीबॉडी होती हैं, जिन्हें प्लाज़्मा सेल बनाते हैं.",
 "डॉक्टर यह जांच कब कहते हैं? जब बिना वजह खून की कमी हो, हड्डियों में दर्द हो, बार बार संक्रमण हो, किडनी की समस्या हो, कैल्शियम ज़्यादा हो, या टोटल प्रोटीन ज़्यादा हो. खासकर मल्टीपल मायलोमा की जांच में.",
 "सबसे अहम चीज़ है एम स्पाइक. सामान्य गामा हिस्सा चौड़ा होता है, क्योंकि कई तरह की एंटीबॉडी होती हैं. लेकिन अगर प्लाज़्मा सेल का एक ही समूह, एक ही तरह का प्रोटीन बहुत ज़्यादा बनाए, तो एक पतली, ऊंची चोटी दिखती है. इसे एम स्पाइक, या मोनोक्लोनल प्रोटीन कहते हैं.",
 "एम स्पाइक का मतलब हमेशा कैंसर नहीं. ज़्यादातर लोगों में यह एम जी यू एस होता है, जो कैंसर नहीं है. मेयो क्लिनिक के अनुसार, पचास साल से ऊपर, लगभग तीन प्रतिशत लोगों में एम जी यू एस होता है. हर साल इनमें से लगभग एक प्रतिशत में बीमारी आगे बढ़ सकती है, इसलिए नियमित जांच ज़रूरी है.",
 "दूसरे पैटर्न भी जानकारी देते हैं. एल्ब्यूमिन कम, लिवर या किडनी की बीमारी, या पोषण की कमी में. अल्फा टू ज़्यादा, सूजन या नेफ्रोटिक सिंड्रोम में. और गामा में चौड़ी बढ़त, पुराने संक्रमण या ऑटोइम्यून बीमारी में.",
 "एम स्पाइक मिले, तो आगे की जांच होती है. इम्यूनोफिक्सेशन, जो बताता है कि प्रोटीन किस प्रकार का है, जैसे आई जी जी, और कप्पा या लैम्डा. सीरम फ्री लाइट चेन, और पेशाब में प्रोटीन की जांच. और ज़रूरत हो, तो बोन मैरो की जांच.",
 "तैयारी. आमतौर पर बस खून का एक सैंपल, कोई खास तैयारी नहीं. फिर भी अपनी लैब के निर्देश मानें. रिपोर्ट में हर हिस्से की मात्रा, और एम स्पाइक है या नहीं, यह लिखा होता है. रिपोर्ट हमेशा अपने डॉक्टर से ही समझें.",
 close_voice("क्या आपने पहले एम स्पाइक के बारे में सुना था?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/spepr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/spep_{i}.wav"],check=True); f=f"/tmp/spep_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/spep_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
